import re

def kvs(t):
    return dict(re.findall(r'(\w+)=([^,\s]+)', t))

def parse(lines):
    heaps = []
    hl = []
    cc = {}
    cl = []
    comp = {}
    pl = []
    pid = {}
    pidl = []
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        m = re.match(r'^(\d+):$', s)
        if m:
            pid = {'pid': m.group(1)}
            pidl.append(i)
            continue
        m = re.match(r"^CodeHeap '([^']*)':\s*(.*)$", s)
        if m:
            row = {'CodeHeap': m.group(1)}
            row.update(kvs(m.group(2)))
            heaps.append(row)
            hl.append(i)
            cur = 'heap'
            continue
        m = re.match(r'^bounds\s*\[\s*([^,\s]+),\s*([^,\s]+),\s*([^,\s\]]+)\s*\]', s)
        if m:
            vals = {'bounds_low': m.group(1), 'bounds_committed': m.group(2), 'bounds_high': m.group(3)}
            if cur == 'heap' and heaps:
                heaps[-1].update(vals)
                hl.append(i)
            else:
                cc.update(vals)
                cl.append(i)
            continue
        m = re.match(r'^CodeCache:\s*(.*)$', s)
        if m:
            cc.update(kvs(m.group(1)))
            cl.append(i)
            cur = 'cc'
            continue
        m = re.match(r'^Compilation:\s*(\w+)(.*)$', s)
        if m:
            comp['Compilation'] = m.group(1)
            comp.update(kvs(m.group(2)))
            pl.append(i)
            cur = 'comp'
            continue
        if cur == 'cc' and '=' in s:
            cc.update(kvs(s))
            cl.append(i)
            continue
    blocks = []
    if pid:
        blocks.append({'name': 'process', 'kind': 'kv', 'lines': pidl, 'records': [pid]})
    if heaps:
        keys = []
        for r in heaps:
            for k in r:
                if k not in keys:
                    keys.append(k)
        rows = [dict((k, r.get(k, '')) for k in keys) for r in heaps]
        blocks.append({'name': 'code_heaps', 'kind': 'table', 'lines': hl, 'records': rows})
    if cc:
        blocks.append({'name': 'code_cache', 'kind': 'kv', 'lines': cl, 'records': [cc]})
    if comp:
        blocks.append({'name': 'compilation', 'kind': 'kv', 'lines': pl, 'records': [comp]})
    return {'blocks': blocks, 'skip': []}
